class Program { static void Main() { Console.WriteLine("Введите целое неотрицательное число n:"); string input = Console.ReadLine(); if (!int.TryParse(input, out int n) || n < 0) { Console.WriteLine("Ошибка: введено некорректное число или отрицательное значение."); return; } int originalN = n; int sum = 0; int count = 0; do { int digit = n % 10; sum += digit; count++; n /= 10; } while (n > 0); Console.WriteLine("Число: {originalN}"); Console.WriteLine("Количество цифр: {count}"); Console.WriteLine("Сумма цифр: {sum}"); } }
